html='''<!doctype html><html lang="th"><meta charset="utf-8"><style>body{background:#20252d;color:#eee;font:16px system-ui;margin:20px}canvas{background:#292b30;max-width:100%}button,select,input{font:inherit;margin:5px}p{max-width:950px}</style><h1>เดินด้วยชิ้นส่วนภาพ · W</h1><p>ภาพชิ้นส่วนคงที่ ผูกริกกับท่ายืนครั้งเดียว · เคลื่อนไหวตามจังหวะและช่วงเท้าลงพื้นจากไกด์</p><canvas id="c" width="512" height="576"></canvas><p><button id="play" disabled>เล่น / หยุด</button><input disabled id="frame" type="range" min="0" max="15" value="0"><select id="speed" disabled><option value="1">1×</option><option value="0.25">¼×</option></select><label><input disabled id="travel" type="checkbox">เดินผ่านพื้น</label><label><input disabled id="loop" type="checkbox" checked>วน</label></p><p id="status">กำลังโหลดภาพ…</p><script src="inputs/sprite-mesh-player.js"></script><script src="inputs/sprite-articulated-player.js"></script><script src="inputs/sprite-clip-clock.cjs"></script><script>const D=__DATA__,$=id=>document.getElementById(id),x=$('c').getContext('2d'),layers=new Map(),footLayers=new Map();let fi=0,clock=new SpriteClipClock({durations:D.durations_ms,loop:true}),last=null;function poseAt(t){let k=Math.max(0,Math.min(256,t*256)),i=Math.min(255,Math.floor(k)),f=k-i,p={};for(const n of Object.keys(D.poses[0]))p[n]=D.poses[i][n].map((a,j)=>a*(1-f)+D.poses[i+1][n][j]*f);return p}function offsetAt(t){let k=Math.max(0,Math.min(256,t*256)),i=Math.min(255,Math.floor(k)),f=k-i;return D.world_offsets[i].map((a,j)=>a*(1-f)+D.world_offsets[i+1][j]*f)}function draw(t=fi/D.durations_ms.length,travel=$('travel').checked,only=null){let p=poseAt(t);const width=travel?768:D.canvas[0],height=travel?768:D.canvas[1];if($('c').width!==width||$('c').height!==height){$('c').width=width;$('c').height=height}x.clearRect(0,0,width,height);let offset=travel?offsetAt(t):[0,0];p.output_offset=travel?[128+offset[0],128+offset[1]]:[0,0];for(const name of D.order){if(only&&only!==name)continue;let m=layers.get(name);m.setViewport(width,height);m.draw(p);x.drawImage(m.canvas,0,0)}$('frame').value=fi;$('status').textContent='เฟรม'+(fi+1)+'/'+D.durations_ms.length;return p}function select(i){clock.seek(D.durations_ms.slice(0,i).reduce((a,b)=>a+b,0));fi=i;draw()}$('frame').oninput=()=>select(+$('frame').value);$('play').onclick=()=>{if(clock.running)clock.cancel();else{clock.clip.loop=$('loop').checked;if(clock.finished||clock.time===0)clock.start();else clock.running=true}last=null};$('travel').onchange=()=>{clock.cancel();if($('travel').checked)$('loop').checked=false;$('loop').disabled=$('travel').checked;clock.seek(0);fi=0;draw()};function tick(now){if(clock.running){fi=clock.advance((last===null?0:Math.max(0,now-last))*+$('speed').value).frame;draw(clock.time/clock.total)}last=now;requestAnimationFrame(tick)}Promise.all(Object.entries(D.definitions).map(([n,d])=>new Promise((ok,no)=>{const im=new Image();im.onload=()=>{try{const a=document.createElement('canvas');layers.set(n,new SpriteArticulatedLayer(a,im,d));if(n.endsWith('_leg')){const f=document.createElement('canvas');f.width=f.height=512;const q=f.getContext('2d');q.drawImage(im,0,0);q.clearRect(0,0,512,d.bands[3]);footLayers.set(n,new SpriteArticulatedLayer(document.createElement('canvas'),f,d))}ok()}catch(e){no(new Error(n+': '+e.message))}};im.onerror=()=>no(new Error('Missing image: '+d.texture));im.src=d.texture}))).then(()=>{$('frame').max=D.durations_ms.length-1;draw();for(const n of ['play','frame','speed','travel','loop'])$(n).disabled=false;window.READY=true;requestAnimationFrame(tick)}).catch(e=>{window.LOAD_ERROR=e.message;$('status').textContent='โหลดชุดภาพไม่ได้: '+e.message;$('play').disabled=true;$('frame').disabled=true});window.study={data:D,layers,poseAt,draw,select,get clock(){return clock},frame(i,travel=false,only=null){draw(i/D.durations_ms.length,travel,only);return $('c').toDataURL('image/png')},footFrame(n,t,heldCount=0,rootGain=1){const m=footLayers.get(n);if(!m)throw Error('Missing foot diagnostic');const p=poseAt(heldCount?Math.floor(t*heldCount)/heldCount:t),o=offsetAt(t);p.output_offset=[128+o[0]*rootGain,128+o[1]*rootGain];m.setViewport(768,768);m.draw(p);if($('c').width!==768){$('c').width=$('c').height=768}x.clearRect(0,0,768,768);x.drawImage(m.canvas,0,0);return $('c').toDataURL('image/png')}};</script></html>''';(P/(prefix+'walk-review.html')).write_text(html.replace('· W','· '+view).replace('__DATA__',json.dumps(data,separators=(',',':'))));print(view+' articulated walk80 samples from257 actual source phases')
